package app.rigweave.mobile

// Simplified Natural Earth 1:110m land outlines.
// Source: https://github.com/nvkelso/natural-earth-vector/blob/master/geojson/ne_110m_land.geojson
// Natural Earth data is public domain. Coordinates are stored longitude,latitude.
internal data class RfLandPoint(val longitude: Double, val latitude: Double)

internal val rfWorldLandContours: List<List<RfLandPoint>> by lazy(LazyThreadSafetyMode.PUBLICATION) {
    NaturalEarthLand.split('|').mapNotNull { contour ->
        contour.split(';').mapNotNull { encoded ->
            val values = encoded.split(',')
            if (values.size != 2) null else {
                val longitude = values[0].toDoubleOrNull()
                val latitude = values[1].toDoubleOrNull()
                if (longitude == null || latitude == null) null else RfLandPoint(longitude, latitude)
            }
        }.takeIf { it.size >= 3 }
    }
}

